def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'
    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    my_D = sum(1 for a in my if a == 'D')
    opp_D = sum(1 for a in opp if a == 'D')
    last_me = my[-1]
    last_opp = opp[-1]
    if opp_D >= n * 0.8 and n >= 3:
        return 'D'
    last_my_def = -1
    for i in range(n-1, -1, -1):
        if my[i] == 'D':
            last_my_def = i
            break
    last_probe_punished = False
    if last_my_def != -1 and last_my_def < n-1:
        if opp[last_my_def + 1] == 'D':
            last_probe_punished = True
    if n >= 99:
        return 'D'
    if n == 98:
        if last_probe_punished:
            return 'C'
        else:
            return 'D'
    if last_opp == 'D':
        if last_me == 'D':
            return 'C'
        else:
            if opp_D <= max(1, n // 10):
                return 'C'
            else:
                return 'D'
    if my_D > opp_D + 2 and n > 10:
        return 'C'
    if opp_D == 0:
        if last_probe_punished:
            return 'C'
        else:
            if last_my_def == -1:
                if n >= 5:
                    return 'D'
                else:
                    return 'C'
            else:
                if n - last_my_def >= 3:
                    return 'D'
                else:
                    return 'C'
    if opp_D <= n * 0.2 and n >= 10:
        if last_probe_punished:
            return 'C'
        else:
            if last_my_def == -1:
                if n >= 10:
                    return 'D'
                else:
                    return 'C'
            else:
                if n - last_my_def >= 5:
                    return 'D'
                else:
                    return 'C'
    return 'C'
